package main

import (
	"net/http"
	"strings"
)

func webHandler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		// The UI template is intentionally embedded as one small static asset.
		// Reset its illustrative defaults before the browser fills them from the
		// API; production must never display demo TLS/fingerprint evidence.
		html := strings.NewReplacer(
			"<b>94</b>", "<b>—</b>",
			"<h3 id=\"profile\">Chrome-like</h3><p>High confidence browser signature</p>", "<h3 id=\"profile\">No selection</h3><p>No observation selected</p>",
			"TLS 1.3 <i class=\"check\">✓</i>", "Not observed",
			"h2 <i class=\"check\">✓</i>", "Not observed",
			"Available <i class=\"check\">✓</i>", "Not observed",
		).Replace(indexHTML)
		html = strings.Replace(html, "</body>", `<script>
(function () {
  function metric(label, value) {
    document.querySelectorAll('.metric').forEach(function (item) {
      var name = item.querySelector('label');
      if (name && name.textContent === label) {
        var target = item.querySelector('.value');
        if (target) target.textContent = value || 'Not observed';
      }
    });
  }
  function render(item) {
    document.querySelector('#profile').textContent = item ? (item.detected_profile || 'Unknown') : 'No selection';
    document.querySelector('.ring b').textContent = '—';
    document.querySelector('.score p').textContent = item ? 'Observed profile; confidence is not inferred here' : 'No observation selected';
    metric('TLS version', item && item.tls_version);
    metric('ALPN', item && item.alpn);
    metric('JA3 fingerprint', item && item.ja3 ? 'Available' : 'Not observed');
    metric('JA4 fingerprint', item && item.ja4 ? 'Available' : 'Not observed');
    metric('HTTP/2 fingerprint', item && item.http2_fingerprint ? 'Available' : 'Not observed');
  }
  render(null);
  fetch('/api/connections').then(function (response) { return response.json(); }).then(function (items) { render(items[0]); }).catch(function () { render(null); });
}());
</script></body>`, 1)
		_, _ = w.Write([]byte(html))
	})
}

const indexHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>httpfin Inspector</title><style>
:root{--bg:#f5f7fb;--ink:#122033;--muted:#738096;--line:#e6ebf2;--blue:#2f61de;--green:#17a673;--card:#fff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 Inter,system-ui,sans-serif}.app{min-height:100vh;display:grid;grid-template-columns:220px 1fr}aside{background:#0f1d31;color:#cfdaea;padding:24px 14px;display:flex;flex-direction:column}.brand{color:#fff;font-weight:700;display:flex;gap:10px;align-items:center;padding:0 12px 35px}.mark{width:31px;height:31px;border-radius:9px;background:var(--blue);display:grid;place-items:center;font-size:18px}.eyebrow{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#7285a5;margin:0 12px 9px}nav{display:grid;gap:5px}nav button{border:0;background:transparent;color:#a9b9cf;text-align:left;padding:11px 12px;border-radius:9px;display:flex;gap:11px;cursor:pointer}nav button.active,nav button:hover{background:#1d3150;color:#fff}.side{margin-top:auto;border-top:1px solid #233650;padding:17px 12px 0;color:#8da0ba;font-size:12px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#35c58c;box-shadow:0 0 0 3px #244a49;margin-right:6px}main{min-width:0}header{height:74px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 36px}.crumb{color:var(--muted)}.crumb strong{color:var(--ink)}.avatar{width:32px;height:32px;border-radius:50%;background:#dbe6ff;color:#315dcc;display:grid;place-items:center;font-size:12px;font-weight:700}.content{max-width:1310px;margin:auto;padding:34px 36px 52px}.title{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:25px}h1{margin:0 0 6px;font-size:29px;letter-spacing:-.035em}.subtitle{color:var(--muted);margin:0}.live{color:#157e5a;background:#e9f8f1;border:1px solid #c9eee0;border-radius:20px;padding:7px 12px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(310px,.85fr);gap:20px}.card{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 10px 30px rgba(24,40,72,.06)}.head{display:flex;align-items:center;justify-content:space-between;padding:20px 21px 17px;border-bottom:1px solid var(--line)}h2{font-size:15px;margin:0}.muted{font-size:12px;color:var(--muted)}.rows{padding:6px 9px 10px}.row{display:grid;grid-template-columns:8px minmax(0,1fr) auto auto;align-items:center;gap:14px;padding:15px 12px;border-radius:9px;cursor:pointer;border:1px solid transparent}.row:hover,.row.selected{background:#f7f9fd;border-color:#e3e9f5}.r-dot{width:7px;height:7px;border-radius:50%;background:#3bc38b}.r-dot.warn{background:#e2a22a}.ip{font-weight:650;font-size:14px}.meta{color:var(--muted);font-size:12px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tag{border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;background:#eaf0ff;color:#315dcc;white-space:nowrap}.tag.warn{background:#fff1ed;color:#c95c3e}.time{font-size:12px;color:#8d99aa}.score{padding:22px 21px 16px;display:flex;gap:16px;align-items:center}.ring{width:84px;height:84px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--blue) 0 94%,#e8eef9 94%);position:relative;font-size:21px;font-weight:750}.ring:after{content:"";position:absolute;inset:7px;background:#fff;border-radius:50%}.ring b{position:relative;z-index:1}.score h3{font-size:16px;margin:0 0 4px}.score p{margin:0;color:var(--muted);font-size:12px}.metrics{border-top:1px solid var(--line);padding:5px 21px 13px}.metric{display:grid;grid-template-columns:1fr auto;align-items:center;padding:13px 0;border-bottom:1px solid #f0f2f6}.metric:last-child{border:0}.metric label{color:var(--muted);font-size:13px}.value{font-weight:650;font-size:13px}.check{color:var(--green);background:#e9f8f1;border-radius:50%;padding:1px 4px;font-size:11px}.detail{margin-top:20px}.tabs{display:flex;gap:21px;padding:0 21px;border-bottom:1px solid var(--line)}.tab{border:0;background:none;padding:15px 0 13px;color:#8793a4;border-bottom:2px solid transparent;font-size:13px;cursor:pointer}.tab.active{color:var(--blue);border-color:var(--blue);font-weight:650}.body{padding:20px 21px 23px;display:grid;grid-template-columns:1fr 1fr;gap:26px}.section h3{margin:0 0 13px;font-size:12px;text-transform:uppercase;letter-spacing:.09em;color:#8a95a7}.kv{display:flex;justify-content:space-between;gap:18px;padding:8px 0;font-size:13px}.kv span:first-child{color:var(--muted)}.kv span:last-child{font-family:monospace;font-size:12px;color:#30425c;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.note{margin-top:18px;color:#9aa5b5;font-size:12px}@media(max-width:900px){.app{grid-template-columns:68px 1fr}aside{padding:20px 9px}.brand span,.eyebrow,nav span,.side{display:none}nav button{justify-content:center}.content{padding:26px 20px}.grid{grid-template-columns:1fr}.title{align-items:flex-start;gap:14px;flex-direction:column}header{padding:0 20px}.body{grid-template-columns:1fr}}@media(max-width:590px){.row{grid-template-columns:8px minmax(0,1fr) auto}.time,.tag{display:none}h1{font-size:24px}}
</style></head><body><div class="app"><aside><div class="brand"><div class="mark">✣</div><span>httpfin<br>Inspector</span></div><p class="eyebrow">Workspace</p><nav><button class="active">▦<span>Overview</span></button><button>⌁<span>Connections</span></button><button>◈<span>Profiles</span></button><button>▤<span>Reports</span></button></nav><div class="side"><span class="dot"></span>Collector online<br><br>Listening on <b style="color:#d9e5f6">:8080</b></div></aside><main><header><div class="crumb"><strong>Workspace</strong> <span style="margin:0 8px;color:#c0c8d3">/</span> Client Fingerprint Inspector</div><div class="avatar">RF</div></header><div class="content"><div class="title"><div><h1>Client Fingerprint Inspector</h1><p class="subtitle">Inspect TLS, HTTP/2 and header signals from incoming connections.</p></div><div class="live"><span class="dot"></span>Live capture</div></div><div class="grid"><section class="card"><div class="head"><div><h2>Recent connections</h2><span class="muted" id="count">Loading…</span></div><a class="muted" href="/api/report">Export report</a></div><div class="rows" id="rows"></div></section><section class="card"><div class="head"><h2>Detected profile</h2><span class="muted">Selected connection</span></div><div class="score"><div class="ring"><b>94</b></div><div><h3 id="profile">Chrome-like</h3><p>High confidence browser signature</p></div></div><div class="metrics"><div class="metric"><label>TLS version</label><span class="value" id="tls">TLS 1.3 <i class="check">✓</i></span></div><div class="metric"><label>ALPN</label><span class="value" id="alpn">h2 <i class="check">✓</i></span></div><div class="metric"><label>JA3 fingerprint</label><span class="value">Available <i class="check">✓</i></span></div><div class="metric"><label>JA4 fingerprint</label><span class="value">Available <i class="check">✓</i></span></div><div class="metric"><label>HTTP/2 fingerprint</label><span class="value">Available <i class="check">✓</i></span></div><div class="metric"><label>User-Agent consistency</label><span class="value" id="ua">Matched <i class="check">✓</i></span></div></div></section></div><section class="card detail"><div class="head"><h2>Connection details</h2><span class="muted" id="detail-title">Select a connection</span></div><div class="tabs"><button class="tab active">Summary</button><button class="tab">TLS ClientHello</button><button class="tab">HTTP/2 settings</button><button class="tab">Headers</button></div><div class="body"><div class="section"><h3>Network</h3><div class="kv"><span>Remote address</span><span id="remote">—</span></div><div class="kv"><span>Protocol</span><span id="proto">—</span></div><div class="kv"><span>Request</span><span id="request">—</span></div></div><div class="section"><h3>Fingerprints</h3><div class="kv"><span>JA3</span><span id="ja3">—</span></div><div class="kv"><span>JA4</span><span id="ja4">—</span></div><div class="kv"><span>HTTP/2</span><span id="h2">—</span></div></div></div></section><div class="note">ⓘ Fingerprints are signals, not proof of identity. Use them alongside application and network telemetry.</div></div></main></div><script>const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));function select(x){$('#profile').textContent=x.detected_profile||'Unknown';$('#tls').innerHTML=esc(x.tls_version||'Not observed')+' <i class="check">✓</i>';$('#alpn').innerHTML=esc(x.alpn||'Not observed')+' <i class="check">✓</i>';$('#ua').innerHTML=esc(x.ua_consistency||'Unknown')+' <i class="check">✓</i>';$('#detail-title').textContent=esc(x.client_ip)+' · '+new Date(x.timestamp).toLocaleString();$('#remote').textContent=x.client_ip;$('#proto').textContent=x.protocol;$('#request').textContent=x.method+' '+x.url;$('#ja3').textContent=x.ja3||'Not observed';$('#ja4').textContent=x.ja4||'Not observed';$('#h2').textContent=x.http2_fingerprint||'Not observed'}fetch('/api/connections').then(r=>r.json()).then(items=>{$('#count').textContent=items.length+' connections observed';$('#rows').innerHTML=items.map((x,i)=>'<div class="row '+(i===0?'selected':'')+'" data-i="'+i+'"><i class="r-dot '+(x.risk==='Review'?'warn':'')+'"></i><div><div class="ip">'+esc(x.client_ip)+'</div><div class="meta">'+esc(x.detected_profile)+' · '+esc(x.tls_version||x.protocol)+' · '+esc(x.alpn||x.protocol)+'</div></div><span class="tag '+(x.risk==='Review'?'warn':'')+'">'+esc(x.detected_profile)+'</span><span class="time">'+(i?'recent':'now')+'</span></div>').join('');items.forEach((x,i)=>$('.row[data-i="'+i+'"]').onclick=()=>select(x));if(items[0])select(items[0])}).catch(()=>$('#count').textContent='API unavailable');document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active')});</script></body></html>`
